-- ============================================================
-- 13. EXAMPLES
-- ============================================================

-- IDs must be supplied by the application:
--
-- INSERT INTO `property`
--     (`property_id`, `property_code`, `address_line`, `province_name`)
-- VALUES
--     (UUID_TO_BIN('...'), 'PT001', '123 Đường X', 'Thành phố Hồ Chí Minh');
--
-- SELECT BIN_TO_UUID(`property_id`) AS `property_id`,
--        `property_code`
-- FROM `property`;
--
-- Application-generated UUID:
--
-- INSERT INTO `property`
