-- ============================================================
-- 14. IMPORTANT PRODUCTION NOTE
-- ============================================================
-- BINARY(16) is used instead of CHAR(36) to keep PK/FK indexes
-- compact and efficient.
--
-- For most backend applications, the preferred architecture is:
--   1. Generate a UUID in the application/service layer.
--   2. Convert it to BINARY(16) before INSERT.
--
-- ORM/query examples:
--   UUID_TO_BIN(?)            -- application UUID string -> BINARY(16)
--   BIN_TO_UUID(id)           -- BINARY(16) -> UUID string
--

SET FOREIGN_KEY_CHECKS = 1;
